using System;using System.Drawing;using System.Windows.Forms;
sealed partial class CaptureEditor {
 internal TextBox textDraft;ThemeNumber textSize;FlowLayoutPanel textControls;internal Point textAt;Point textDragOffset;bool movingText;
 internal void BeginTextDraft(Point at){if(textDraft!=null){textAt=at;canvas.Invalidate();textDraft.Focus();return;}textAt=at;textControls=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=80,Padding=new Padding(8),AutoScroll=true};textDraft=new TextBox{Multiline=true,Width=280,Height=52,Text=""};textSize=new ThemeNumber{Minimum=10,Maximum=120,Value=24,Width=82};var apply=new Button{Text="Apply text",AutoSize=true};var cancel=new Button{Text="Cancel",AutoSize=true};textControls.Controls.Add(textDraft);textControls.Controls.Add(textSize);textControls.Controls.Add(apply);textControls.Controls.Add(cancel);Controls.Add(textControls);textControls.BringToFront();owner.ThemeControls(textControls);textDraft.TextChanged+=(s,e)=>canvas.Invalidate();textSize.ValueChanged+=(s,e)=>canvas.Invalidate();apply.Click+=(s,e)=>CommitTextDraft();cancel.Click+=(s,e)=>CancelTextDraft();hint.Text="Type below · drag text to position it · Ctrl+Enter applies · Esc cancels";textDraft.Focus();canvas.Invalidate();}
 Rectangle TextDraftBox(){if(textDraft==null)return Rectangle.Empty;using(var font=new Font("Segoe UI",(float)textSize.Value*ImageBox().Width/image.Width,FontStyle.Bold))using(var graphics=canvas.CreateGraphics()){var size=graphics.MeasureString(String.IsNullOrEmpty(textDraft.Text)?"Text":textDraft.Text,font);return new Rectangle(FromImage(textAt),new Size(Math.Max(24,(int)Math.Ceiling(size.Width)),Math.Max(24,(int)Math.Ceiling(size.Height))));}}
 void PaintTextDraft(Graphics graphics){if(textDraft==null)return;using(var font=new Font("Segoe UI",(float)textSize.Value*ImageBox().Width/image.Width,FontStyle.Bold))using(var brush=new SolidBrush(color))using(var outline=new Pen(color,1)){graphics.TextRenderingHint=System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;graphics.DrawString(String.IsNullOrEmpty(textDraft.Text)?"Text":textDraft.Text,font,brush,FromImage(textAt));outline.DashStyle=System.Drawing.Drawing2D.DashStyle.Dash;graphics.DrawRectangle(outline,TextDraftBox());}}
 internal void CommitTextDraft(){if(textDraft==null)return;string value=textDraft.Text;float size=(float)textSize.Value;Point at=textAt;CancelTextDraft();if(!String.IsNullOrWhiteSpace(value))DrawText(at,value,size);}
 internal void CancelTextDraft(){if(textDraft==null)return;var controls=textControls;textDraft=null;textSize=null;textControls=null;movingText=false;canvas.Capture=false;Controls.Remove(controls);controls.Dispose();canvas.Invalidate();}
}
